import{bV as a,aL as s,u as i,G as n}from"./chunks/framework.DvBUyM1S.js";const b=JSON.parse('{"title":"Mac必备工具 — Homebrew国内源","description":"","frontmatter":{"title":"Mac必备工具 — Homebrew国内源","date":"2022-01-08T19:41:13.000Z","permalink":"/pages/70e61d/","categories":[null],"tags":[null]},"headers":[],"relativePath":"06.工具/03.Mac/02.Mac开发必备工具—Homebrew国内源.md","filePath":"06.工具/03.Mac/02.Mac开发必备工具—Homebrew国内源.md","lastUpdated":1652233015000}'),t={name:"06.工具/03.Mac/02.Mac开发必备工具—Homebrew国内源.md"};function l(r,e,o,c,p,d){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="mac必备工具-—-homebrew国内源" tabindex="-1">Mac必备工具 — Homebrew国内源 <a class="header-anchor" href="#mac必备工具-—-homebrew国内源" aria-label="Permalink to &quot;Mac必备工具 — Homebrew国内源&quot;">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><p><code>Homebrew</code>是一款包管理工具，目前支持<code>macOS</code>和<code>Linux</code>系统。</p><p>由于官方提供下载地址，经常安装等待一段时间之后遇到下面提示</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/bin/bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">//</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 报错</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (7) Failed to connect to raw.githubusercontent.com port 443: Operation timed out</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>经过多次测试，发现<code>raw.githubusercontent.com</code>访问很不稳定，我们中国大陆用户访问的话经常容易访问不到其资源。</p><p>好奇为什么官方不通过<code>JSDelivr</code>等免费的CDN解决该问题？</p><p>所以在此基于官方的源码上修改其中<code>raw.githubusercontent.com</code>切换成中科大镜像，亲测速度还不错，哈哈放心食用。</p><h2 id="快速安装" tabindex="-1">快速安装 <a class="header-anchor" href="#快速安装" aria-label="Permalink to &quot;快速安装&quot;">​</a></h2><p><strong>JSDelivr</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/bin/bash -c &quot;$(curl -fsSL https://cdn.jsdelivr.net/gh/qqlcx5/homebrew/install.sh)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>码云</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/bin/bash -c &quot;$(curl -fsSL https://gitee.com/qqlcx5/homebrew/raw/master/install.sh)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p><strong>JSDelivr</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/bin/bash -c &quot;$(curl -fsSL https://cdn.jsdelivr.net/gh/qqlcx5/homebrew/uninstall.sh)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>码云</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/bin/bash -c &quot;$(curl -fsSL https://gitee.com/qqlcx5/homebrew/raw/master/uninstall.sh)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h3><ul><li><code>brew help</code> 查看帮助</li><li><code>brew list</code> 列出已安装的软件包</li><li><code>brew install &lt;package name&gt;</code> 安装软件包</li><li><code>brew uninstall &lt;package name&gt;</code> 卸载软件包</li><li><code>brew search &lt;package name&gt;</code> 查找软件包</li><li><code>brew info &lt;package name&gt;</code> 查看软件包信息</li><li><code>brew -v</code> 查看<code>brew</code>版本</li><li><code>brew update</code> 更新<code>brew</code></li><li><code>brew outdated</code> 列出需要更新的软件包</li><li><code>brew upgrade [&lt;package name&gt;]</code>可选指定更新某个软件包，默认更新所有软件包</li></ul>`,20)])])}const u=a(t,[["render",l]]);export{b as __pageData,u as default};
